UPDATE sys_dictionary
SET dic_value =
CASE
        WHEN dic_key = 'aliyun_appkey' THEN #{smsVO.aliyunAppkey}
        WHEN dic_key = 'aliyun_appserve' THEN #{smsVO.aliyunAppserve}
        WHEN dic_key = 'aliyun_signname' THEN #{smsVO.aliyunSignname}
        WHEN dic_key = 'aliyun_templatecode' THEN #{smsVO.aliyunTemplatecode}
END
WHERE
    dic_sort = 'sms'

